// Sugerencia de horario (29-oct): con el rendimiento real de los posts de Facebook e Instagram de
// los últimos 60 días, sugiere el mejor día y hora para publicar y lo guarda en G54
// (PUT /api/agent/companies/{id}/sugerencia-horario; el editor de posts del panel lo muestra con "Usar").
// Piso mínimo (decisión de la usuaria, 26-oct): 3 horarios con 5 posts medidos cada uno y el mejor
// al menos 20 % por encima del segundo. Si no, la sugerencia queda vacía y se devuelve el motivo.
// Cada red se compara contra su propio promedio (alcance + 3 × interacciones). LinkedIn todavía no
// entra: falta el permiso de estadísticas. Nunca frena el informe: cualquier error se devuelve como motivo.
const entrada = $input.first().json;
try {
  const cfg = $('⚙️ Config Growth54').item.json;
  const B = cfg.G54_BASE_URL;
  const cid = parseInt(cfg.G54_COMPANY_ID, 10) || 1;
  const PAGE = cfg.FB_PAGE_ID;
  const PT = $('🔑 Obtener Page Token FB').item.json.access_token;
  const IGID = $('🔑 Obtener Tokens Sociales G64').item.json.ig_user_id;
  let tz = 'America/New_York';
  try { tz = ($('📊 Obtener Perfil Empresa').item.json.data || {}).timezone || tz; } catch (e) {}
  const H = { Accept: 'application/json', 'Content-Type': 'application/json' };
  const G = 'https://graph.facebook.com/v19.0/';
  const desde = new Date(Date.now() - 60 * 86400000).toISOString().slice(0, 10);
  const get = async (path, params) => {
    const qs = Object.entries({ ...params, access_token: PT }).map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(v)).join('&');
    try { return await this.helpers.httpRequest({ method: 'GET', url: G + path + '?' + qs, json: true, timeout: 30000 }); } catch (e) { return null; }
  };
  const sumObj = v => (v && typeof v === 'object') ? Object.values(v).reduce((a, b) => a + (Number(b) || 0), 0) : (Number(v) || 0);

  // Métricas actuales de Meta por id
  const metricas = {};
  if (PAGE && PT) {
    const r = await get(PAGE + '/published_posts', { since: desde, limit: 100,
      fields: 'id,insights.metric(post_total_media_view_unique,post_reactions_by_type_total,post_clicks_by_type,post_activity_by_action_type)' });
    for (const p of ((r && r.data) || [])) {
      const ins = (p.insights && p.insights.data) || [];
      const val = n => { const x = ins.find(i => i.name === n); return x && x.values && x.values[0] ? sumObj(x.values[0].value) : 0; };
      const acts = ((ins.find(i => i.name === 'post_activity_by_action_type') || {}).values || [{}])[0].value || {};
      metricas[String(p.id)] = { alcance: val('post_total_media_view_unique'),
        interacciones: val('post_reactions_by_type_total') + val('post_clicks_by_type') + (Number(acts.comment) || 0) + (Number(acts.share) || 0) };
    }
  }
  if (IGID && PT) {
    const media = await get(IGID + '/media', { fields: 'id,timestamp', since: desde, limit: 100 });
    for (const md of ((media && media.data) || [])) {
      const mi = await get(md.id + '/insights', { metric: 'reach,total_interactions' });
      const mv = n => { const x = ((mi && mi.data) || []).find(y => y.name === n); return (x && x.values && x.values[0] && Number(x.values[0].value)) || 0; };
      metricas[String(md.id)] = { alcance: mv('reach'), interacciones: mv('total_interactions') };
    }
  }

  // Posts publicados de G54 (con su hora real de publicación), cruzados con las métricas por su id de Meta
  const login = await this.helpers.httpRequest({ method: 'POST', url: B + '/api/auth/login', headers: H, json: true,
    body: { email: cfg.G54_MASTER_EMAIL, password: cfg.G54_MASTER_PASSWORD } });
  const auth = { ...H, Authorization: 'Bearer ' + login.access_token };
  await this.helpers.httpRequest({ method: 'POST', url: B + '/api/auth/switch-company', headers: auth, json: true, body: { company_id: cid } });
  const resp = await this.helpers.httpRequest({ method: 'GET', url: B + '/api/rrss/posts', headers: auth, json: true });
  const posts = [];
  for (const p of ((resp && resp.data) || resp || [])) {
    if (p.status !== 'publicado' || !p.fecha_publicada || !p.post_id_platform) continue;
    const id = String(p.post_id_platform);
    const m = metricas[id] || metricas[id.split('_').pop()];
    if (!m) continue;  // LinkedIn, o un post que Meta ya no devuelve
    posts.push({ platform: p.platform, fecha_publicada: p.fecha_publicada, alcance: m.alcance, interacciones: m.interacciones });
  }

  // ---- Cálculo (probado aparte el 29-oct con los mismos casos) ----
  const calcularSugerencia = (posts, tz, ahora) => {
    const MIN_POSTS = 5, MIN_HORARIOS = 3, VENTAJA = 1.2;
    const DIAS = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
    const partes = (iso) => {
      const f = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: '2-digit', hourCycle: 'h23', weekday: 'short' }).formatToParts(new Date(iso));
      return { hora: Number(f.find((p) => p.type === 'hour').value),
               wd: ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(f.find((p) => p.type === 'weekday').value) };
    };
    const medidos = posts.filter((p) => p.fecha_publicada && Number.isFinite(p.alcance));
    const porRed = {};
    for (const p of medidos) (porRed[p.platform] = porRed[p.platform] || []).push(p.alcance + 3 * (p.interacciones || 0));
    const prom = {};
    for (const [red, v] of Object.entries(porRed)) prom[red] = Math.max(1, v.reduce((a, b) => a + b, 0) / v.length);
    const grupos = {}, dias = {};
    for (const p of medidos) {
      const { hora, wd } = partes(p.fecha_publicada);
      const puntaje = (p.alcance + 3 * (p.interacciones || 0)) / prom[p.platform];
      (grupos[hora] = grupos[hora] || []).push(puntaje);
      (dias[wd] = dias[wd] || []).push(puntaje);
    }
    const media = (v) => v.reduce((a, b) => a + b, 0) / v.length;
    const conPiso = Object.entries(grupos).filter(([, v]) => v.length >= MIN_POSTS)
      .map(([h, v]) => ({ hora: Number(h), n: v.length, media: media(v) })).sort((a, b) => b.media - a.media);
    const hhmm = (h) => String(h).padStart(2, '0') + ':00';
    if (conPiso.length < MIN_HORARIOS) {
      const detalle = Object.entries(grupos).map(([h, v]) => `${hhmm(Number(h))}: ${v.length}`).join(', ') || 'ninguno';
      return { motivo: `Faltan datos: hacen falta ${MIN_HORARIOS} horarios con ${MIN_POSTS} posts medidos cada uno y hay ${conPiso.length} (posts por horario: ${detalle}).` };
    }
    const [mejor, segundo] = conPiso;
    if (mejor.media < segundo.media * VENTAJA) {
      return { motivo: `Sin una diferencia clara: el mejor horario (${hhmm(mejor.hora)}) rinde ${Math.round((mejor.media / segundo.media - 1) * 100)} % más que el segundo (${hhmm(segundo.hora)}), y hace falta al menos ${Math.round((VENTAJA - 1) * 100)} %.` };
    }
    const diaOk = Object.entries(dias).filter(([, v]) => v.length >= MIN_POSTS)
      .map(([d, v]) => ({ wd: Number(d), media: media(v) })).sort((a, b) => b.media - a.media)[0];
    const hoy = partes(ahora.toISOString());
    const wd = diaOk ? diaOk.wd : ((hoy.wd + 1) % 7 === 0 ? 1 : (hoy.wd + 1) % 7 === 6 ? 1 : (hoy.wd + 1) % 7);
    let delta = (wd - hoy.wd + 7) % 7;
    if (delta === 0) delta = 7;
    const fecha = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(new Date(ahora.getTime() + delta * 86400000));
    return { dia: DIAS[wd], hora: hhmm(mejor.hora), fecha,
      motivo: `A las ${hhmm(mejor.hora)} tus posts rinden ${Math.round((mejor.media / segundo.media - 1) * 100)} % más que a las ${hhmm(segundo.hora)} (${mejor.n} y ${segundo.n} posts medidos).` };
  };
  const sug = calcularSugerencia(posts, tz, new Date());

  // Con día y hora la guarda; sin ellos, G54 deja la sugerencia vacía.
  const body = sug.dia ? { dia: sug.dia, hora: sug.hora, fecha: sug.fecha, motivo: sug.motivo } : { motivo: sug.motivo };
  await this.helpers.httpRequest({ method: 'PUT', url: B + '/api/agent/companies/' + cid + '/sugerencia-horario', json: true,
    headers: { ...H, Authorization: 'Bearer ' + cfg.G54_AGENT_TOKEN }, body });
  try { await this.helpers.httpRequest({ method: 'POST', url: B + '/api/auth/logout', headers: auth, json: true }); } catch (e) {}
  return [{ json: { ...entrada, sugerencia_horario: { ...sug, posts_medidos: posts.length } } }];
} catch (e) {
  return [{ json: { ...entrada, sugerencia_horario: { error: String(e.message || e).slice(0, 200) } } }];
}

