const groqRaw = $('🤖 Groq: Analytics AI').item.json;
const texto = groqRaw.choices?.[0]?.message?.content || '';

const get = (label) => {
  const regex = new RegExp(`(?:^|\\n)\\*{0,2}\\s*${label}\\s*\\*{0,2}[:\\s]+([\\s\\S]*?)(?=\\n\\*{0,2}[A-ZÁÉÍÓÚ][A-ZÁÉÍÓÚ\\s]+\\*{0,2}:|$)`, 'i');
  const match = texto.match(regex);
  return (match?.[1] || '').trim();
};

const reporte = get('REPORTE');
const topContenido = get('TOP CONTENIDO');
const bajoRendimiento = get('BAJO RENDIMIENTO');
const insightsSEO = get('INSIGHTS SEO');
const insightsAEO = get('INSIGHTS AEO');
const insightsGEO = get('INSIGHTS GEO');
const insightsConversion = get('INSIGHTS CONVERSI[ÓO]N');
const recomendaciones = get('RECOMENDACIONES');

const datos = $('🔧 Preparar Datos Analytics').item.json;

return [{ json: {
  reporte,
  topContenido,
  bajoRendimiento,
  insightsSEO,
  insightsAEO,
  insightsGEO,
  insightsConversion,
  recomendaciones,
  texto_completo: texto,
  nombreEmpresa: datos.nombreEmpresa,
  emailEmpresa: datos.emailEmpresa,
  totalPosts: datos.totalPosts,
  totalLeads: datos.totalLeads,
  leadsCalientes: datos.leadsCalientes,
  periodoAnalisis: datos.periodoAnalisis
}}];

const config  = $('⚙️ Config Growth54').item.json;
const now = new Date();
const periodEnd = now.toISOString().slice(0,10);
const periodStart = new Date(now - 7*86400000).toISOString().slice(0,10);

let alcanceFB = 0, engFB = 0, cliquesFB = 0, reaccionesFB = 0, postCount = 0;
let alcanceIG = 0, engIG = 0, cliqueIG = 0, profileViewsIG = 0;

// FB post-level metrics
try {
  const fbPosts = ($('📊 Graph API: FB Insights').item?.json?.data || []);
  postCount = fbPosts.length;
  fbPosts.forEach(p => {
    const ins = p.insights?.data || [];
    const getVal = (name) => ins.find(i => i.name === name)?.values?.[0]?.value || 0;
    const getObjSum = (name) => {
      const v = ins.find(i => i.name === name)?.values?.[0]?.value;
      if (!v) return 0;
      if (typeof v === 'object') return Object.values(v).reduce((a,b) => a+b, 0);
      return v;
    };
    alcanceFB    += getVal('post_fan_reach');
    reaccionesFB += getVal('post_reactions_like_total');
    cliquesFB    += getObjSum('post_clicks_by_type');
    engFB        += getVal('post_reactions_like_total') + getObjSum('post_clicks_by_type');
  });
} catch(e) {}

// IG account-level metrics (metric_type=total_value)
try {
  const igData = ($('📊 Graph API: IG Insights').item?.json?.data || []);
  const getIG = (name) => igData.find(m => m.name === name)?.total_value?.value || 0;
  alcanceIG     = getIG('reach');
  profileViewsIG = getIG('profile_views');
  engIG         = getIG('accounts_engaged');
  cliqueIG      = getIG('website_clicks');
} catch(e) {}

const engRateFB = (alcanceFB > 0) ? parseFloat((engFB / alcanceFB * 100).toFixed(2)) : 0;
const engRateIG = (alcanceIG > 0) ? parseFloat((engIG / alcanceIG * 100).toFixed(2)) : 0;

return [{
  json: {
    period_start: periodStart,
    period_end: periodEnd,
    fb: { alcance: alcanceFB, engagement: engFB, clics: cliquesFB, reacciones: reaccionesFB, posts: postCount },
    ig: { alcance: alcanceIG, engagement: engIG, clics: cliqueIG, profile_views: profileViewsIG },
    engagement_rate_fb: engRateFB,
    engagement_rate_ig: engRateIG,
    engagement_rate: engRateFB
  }
}];

const query = $('🌐 Trigger Webhook').item.json.query || {};
const body  = $('🌐 Trigger Webhook').item.json.body  || {};
const postId    = query.post_id    || body.post_id;
const companyId = query.company_id || body.company_id || $('⚙️ Config Growth54').item.json.G54_COMPANY_ID;

const insData = $('📊 Meta API: Post Insights').item?.json?.data || [];

const getVal = (name) => insData.find(i => i.name === name)?.values?.[0]?.value || 0;
const getObjSum = (name) => {
  const v = insData.find(i => i.name === name)?.values?.[0]?.value;
  if (!v) return 0;
  if (typeof v === 'object') return Object.values(v).reduce((a,b) => a+b, 0);
  return v;
};

const alcance    = getVal('post_fan_reach');
const reacciones = getVal('post_reactions_like_total');
const clics      = getObjSum('post_clicks_by_type');
const engagement = reacciones + clics;
const engRate    = alcance > 0 ? parseFloat((engagement / alcance * 100).toFixed(2)) : 0;
const today      = new Date().toISOString().slice(0,10);

return [{
  json: {
    company_id: parseInt(companyId) || 1,
    post_id: postId,
    platform: String(postId).includes('_') ? 'facebook' : 'instagram',
    period_start: today,
    period_end: today,
    alcance_total: alcance,
    impresiones_total: alcance,
    engagement_total: engagement,
    engagement_rate_avg: engRate,
    clics_total: clics,
    leads_total: 0
  }
}];

